def transform2(g, key):
    h=len(g); w=len(g[0])
    shapes=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v and (r,c) not in seen:
                # BFS same-color component
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and (ny,nx) not in seen:
                            stack.append((ny,nx))
                rows=[p[0] for p in comp]; cols=[p[1] for p in comp]
                shapes.append((v,min(rows),min(cols),max(rows)-min(rows)+1,max(cols)-min(cols)+1,len(comp)))
    shapes.sort(key=key)
    out=[[0]*w for _ in range(h)]
    r=c=0
    for v,r0,c0,rh,cw,n in shapes:
        for dr in range(rh):
            for dc in range(cw):
                if 0<=r+dr<h and 0<=c+dc<w: out[r+dr][c+dc]=v
        r+=rh-1; c+=cw-1
    return out

